WITH exploded AS (SELECT id, service, host, log_ts, latency_ms, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, value) SELECT CASE WHEN latency_ms >= 2137 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, BIT_AND(latency_ms) AS latency_ms_bit_and, COUNT(*) AS event_count, APPROX_PERCENTILE(latency_ms, ARRAY(0.25, 0.5, 0.75)) AS latency_ms_quartiles, COUNT(*) FILTER (WHERE service = 'search') AS search_rows, COUNT(DISTINCT host) AS distinct_hosts, MIN(log_ts) AS first_seen FROM exploded GROUP BY 1;
